rows.vgi.example_queries:
[
  {"description": "Count how many barcode/QR symbologies this worker supports.", "sql": "SELECT count(*) AS supported_formats FROM barcode.main.barcode_formats"},
  {"description": "List the Code-family symbologies (CODE_39/93/128) alphabetically.", "sql": "SELECT format FROM barcode.main.barcode_formats WHERE format LIKE 'CODE%' ORDER BY format"},
  {"description": "Symbology coverage: detect the format of each image in a label set and count labels per supported symbology, listing unused symbologies with 0.", "sql": "WITH labels AS (SELECT barcode.main.generate_qr(t.ticket) AS png FROM (VALUES ('ticket-001'), ('ticket-002')) AS t(ticket) UNION ALL SELECT barcode.main.generate_barcode('5901234123457', 'EAN_13') UNION ALL SELECT barcode.main.generate_barcode('PALLET-77', 'CODE_128')) SELECT f.format, count(l.png) AS labels FROM barcode.main.barcode_formats AS f LEFT JOIN labels AS l ON barcode.main.barcode_format(l.png) = f.format GROUP BY f.format ORDER BY labels DESC, f.format"}
]
